'use client';

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import Link from 'next/link';
import { formatMoney as money, parseMoney, currencyDigits } from './money';

type Mode = 'customer' | 'partner' | 'admin' | 'developer';
type User = { id: string; email: string; name: string; role: string; tenantId: string };
type Item = Record<string, unknown>;
type Field = { name: string; label: string; type?: string; required?: boolean; placeholder?: string; options?: { value: string; label: string }[]; min?: string; max?: string; defaultValue?: string; currency?: unknown };
const menus: Record<Mode, [string, string][]> = {
  customer: [['marketplace', 'Find cover'], ['quotes', 'Your quotes'], ['policies', 'Your policies'], ['claims', 'Claims & support'], ['complaints', 'Complaints']],
  partner: [['underwriting', 'Underwriting'], ['claims', 'Claims workbench'], ['ledger', 'Financial ledger'], ['settlements', 'Settlements'], ['products', 'Product approvals'], ['adapters', 'Provider approvals']],
  admin: [['overview', 'Overview'], ['tenants', 'Organizations'], ['products', 'Product studio'], ['adapters', 'Provider registry'], ['complaints', 'Complaints'], ['audit', 'Audit trail']],
  developer: [['keys', 'API credentials'], ['webhooks', 'Webhooks'], ['logs', 'Webhook deliveries'], ['docs', 'API reference']],
};
const descriptions: Record<string, string> = {
  marketplace: 'Compare published products and find coverage that fits your life.', quotes: 'Review your prices, underwriting decisions and next steps.', policies: 'Your active cover, documents and policy changes in one place.', claims: 'Report an incident, add evidence and follow every decision.',
  complaints: 'Raise a concern, follow its progress and review the response.',
  underwriting: 'Make considered decisions on quotes referred for review.', ledger: 'Trace every posted movement through the balanced ledger.', settlements: 'Review settlement batches and keep approvals independent.', overview: 'A live view of your organization and insurance operations.', tenants: 'Organizations operating on the platform.', adapters: 'Configure certified provider versions and independently approve their bindings.', products: 'Create and independently approve immutable product versions with defined coverage.', audit: 'The record of who did what, and when.', keys: 'Create and revoke credentials for your integrations.', webhooks: 'Connect approved endpoints to insurance lifecycle events.', logs: 'Inspect recorded webhook deliveries, HTTP results and retry attempts.', docs: 'Explore the live OpenAPI contract published by this service.',
};
function text(value: unknown): string { return value === undefined || value === null ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value); }
function date(value: unknown): string { if (!value) return '—'; const parsed = new Date(String(value)); return Number.isNaN(parsed.valueOf()) ? text(value) : parsed.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }); }
class ApiError extends Error { constructor(message: string, readonly status: number, readonly requestId?: string) { super(requestId ? message + ' (request ' + requestId + ')' : message); } }
async function request(path: string, init?: RequestInit) {
  const response = await fetch('/api' + path, { ...init, credentials: 'same-origin', cache: 'no-store', headers: { ...(init?.body && !(init.body instanceof FormData) ? { 'content-type': 'application/json' } : {}), ...init?.headers } });
  if (response.status === 204) return null;
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new ApiError(result.error?.message || result.message || 'The request could not be completed.', response.status, result.requestId);
  return result;
}
function InputField({ field }: { field: Field }) {
  return <label className="field"><span>{field.label}{field.type === 'money' && typeof field.currency === 'string' ? ` (${field.currency.toUpperCase()})` : ''}{field.required !== false ? <span aria-hidden="true"> *</span> : null}</span>{field.type === 'textarea' ? <textarea name={field.name} defaultValue={field.defaultValue} required={field.required !== false} placeholder={field.placeholder} rows={3} /> : field.options ? <select name={field.name} defaultValue={field.defaultValue} required={field.required !== false}><option value="">Choose an option</option>{field.options.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : <input name={field.name} type={field.type === 'money' ? 'text' : field.type || 'text'} inputMode={field.type === 'money' ? 'decimal' : undefined} defaultValue={field.defaultValue} required={field.required !== false} placeholder={field.placeholder || (field.type === 'money' ? (() => { try { const digits = currencyDigits(field.currency); return digits ? '0.' + '0'.repeat(digits) : '0'; } catch { return 'Choose currency first'; } })() : undefined)} min={field.min} max={field.max} step={field.type === 'number' || field.type === 'datetime-local' ? '1' : undefined} autoComplete={field.name === 'password' ? 'current-password' : field.name === 'email' ? 'email' : 'off'} />}</label>;
}
const sandboxRatingExample = JSON.stringify({version:'sandbox-rating-v1',effectiveFrom:'2020-01-01T00:00:00Z',effectiveUntil:'2100-01-01T00:00:00Z',ageFactors:[{minAge:18,maxAge:24,numerator:'125',denominator:'100'},{minAge:25,maxAge:100,numerator:'1',denominator:'1'}],assetRateBps:0,taxBps:800,feeMinor:'500',referAboveAge:70}, null, 2);
function AdvancedProductFields({ adapters }: { adapters: Item[] }) {
  const approved = adapters.filter(adapter => adapter.status === 'APPROVED');
  const providerOptions = (kind: string) => approved.filter(adapter => adapter.kind === kind).map(adapter => ({ value: text(adapter.id), label: text(adapter.name) + ' · ' + text(adapter.version) }));
  const fields: Field[] = [
    { name: 'jurisdiction', label: 'Jurisdiction code', required: false, defaultValue: 'SANDBOX' },
    { name: 'certificationReference', label: 'Product certification reference', required: false, placeholder: 'Approved certification record or reference' },
    { name: 'carrierAdapterId', label: 'Approved carrier provider', options: providerOptions('CARRIER'), required: false },
    { name: 'paymentAdapterId', label: 'Approved payment provider', options: providerOptions('PAYMENT'), required: false },
    { name: 'terms', label: 'Contract terms', type: 'textarea', required: false, placeholder: 'Paste the exact approved contract terms.' },
    { name: 'ratingRules', label: 'Certified rating definition (JSON)', type: 'textarea', required: false, placeholder: 'Paste the approved effective rules, age factors, asset rate, tax, fee and referral threshold.' },
  ];
  return <details className="advanced-fields"><summary>Jurisdiction, rating and live provider bindings<span>Advanced configuration</span></summary><p>Sandbox defaults remain available for development. A live jurisdiction requires explicit approved terms, effective rating rules, certification and both approved provider versions. Values are validated and calculated by the insurance service.</p><div className="advanced-grid">{fields.map(field => <InputField key={field.name} field={field} />)}</div>{!approved.length && <p className="hint">No provider versions are approved yet. Create a draft in Provider registry and have an independent approver review it before configuring live bindings.</p>}<details><summary>Sandbox rating example<span>Demonstration only</span></summary><p className="hint">This matches the sandbox engine. It is not a live jurisdiction-approved rate definition. Replace the example with your certified rules for a live product.</p><pre>{sandboxRatingExample}</pre><button type="button" className="secondary" onClick={event => { const field = event.currentTarget.form?.elements.namedItem('ratingRules'); if (field instanceof HTMLTextAreaElement) field.value = sandboxRatingExample; }}>Use sandbox example</button></details></details>;
}
function Form({ title, fields, submit = 'Save', onSubmit, onChange, children }: { title: string; fields: Field[]; submit?: string; onSubmit: (data: Record<string, string>, form: HTMLFormElement) => Promise<void>; onChange?: (form: HTMLFormElement) => void; children?: ReactNode }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function handle(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; setBusy(true); setError('');
    try { await onSubmit(Object.fromEntries(Array.from(new FormData(form)).filter((entry): entry is [string, string] => typeof entry[1] === 'string')), form); }
    catch (error) { setError(error instanceof Error ? error.message : 'Please try again.'); }
    finally { setBusy(false); }
  }
  return <section className="form-panel"><h2>{title}</h2><form onSubmit={handle} onChange={event => onChange?.(event.currentTarget)}>{fields.map(field => <InputField key={field.name} field={field} />)}{children}{error && <p className="error" role="alert">{error}</p>}<button disabled={busy} type="submit">{busy ? 'Working…' : submit}<span aria-hidden="true"> →</span></button></form></section>;
}
function CoverageChoices({ product }: { product: Item }) {
  return <fieldset className="coverage-choices" key={text(product.id)}><legend>Choose your coverages</legend>{(Array.isArray(product.coverages) ? product.coverages as Item[] : []).map(coverage => <label className="check-field" key={text(coverage.code)}><input type="checkbox" name="coverageCodes" value={text(coverage.code)} defaultChecked /><span>{text(coverage.name)}<small>Limit {money(coverage.limitMinor, product.currency)} · Deductible {money(coverage.deductibleMinor, product.currency)}</small></span></label>)}</fieldset>;
}
function QuoteReview({ quote }: { quote: Item }) {
  const coverages = Array.isArray(quote.coverages) ? quote.coverages as Item[] : [];
  const answers = quote.answers && typeof quote.answers === 'object' ? quote.answers as Item : {};
  return <section className="quote-review" aria-label="Immutable coverage and contract review"><dl className="certification-facts"><div><dt>Jurisdiction</dt><dd>{text(quote.jurisdiction)}</dd></div><div><dt>Product version</dt><dd>{text(quote.productVersionId)}</dd></div><div><dt>Applicant age</dt><dd>{text(answers.age)}</dd></div><div><dt>Insured asset value</dt><dd>{money(answers.assetValueMinor, quote.currency)}</dd></div></dl><h3>Your quoted coverage</h3>{coverages.length ? <Table rows={coverages} columns={[{ label: 'Coverage', key: 'name' }, { label: 'Limit', key: 'limitMinor', render: item => money(item.limitMinor, quote.currency) }, { label: 'Deductible', key: 'deductibleMinor', render: item => money(item.deductibleMinor, quote.currency) }]} /> : <p className="error">Coverage details are unavailable. Refresh your quote before purchase.</p>}{typeof quote.terms === 'string' && quote.terms.trim() ? <details open><summary>Contract terms for this quote</summary><p className="contract-terms">{quote.terms}</p></details> : <p className="error">Contract terms are unavailable. Refresh your quote before purchase.</p>}</section>;
}
function Status({ value }: { value: unknown }) { return <span className={'status status-' + text(value).toLowerCase()}>{text(value).replaceAll('_', ' ')}</span>; }
function Empty({ children }: { children: ReactNode }) { return <div className="empty"><span className="empty-mark" aria-hidden="true">◇</span><h2>Nothing here yet</h2><p>{children}</p></div>; }
function Table({ rows, columns, actions }: { rows: Item[]; columns: { label: string; key: string; render?: (item: Item) => ReactNode }[]; actions?: (item: Item) => ReactNode }) {
  return <div className="table-scroll"><table><thead><tr>{columns.map(column => <th key={column.key}>{column.label}</th>)}{actions && <th>Actions</th>}</tr></thead><tbody>{rows.map((item, index) => <tr key={text(item.id ?? index)} data-resource-id={typeof item.id === 'string' ? item.id : undefined}>{columns.map(column => <td key={column.key}>{column.render ? column.render(item) : text(item[column.key])}</td>)}{actions && <td><div className="row-actions">{actions(item)}</div></td>}</tr>)}</tbody></table></div>;
}

function Notifications({ revision }: { revision: number }) {
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<Item[] | null>(null);
  const [error, setError] = useState('');
  const [pending, setPending] = useState('');
  const keys = useRef(new Map<string, string>());
  const trigger = useRef<HTMLButtonElement>(null);
  const load = useCallback(async () => {
    setError('');
    try { const result = await request('/notifications'); if (!Array.isArray(result)) throw new Error('Notifications could not be loaded.'); setItems(result); }
    catch (error) { setItems(null); setError(error instanceof Error ? error.message : 'Notifications could not be loaded.'); }
  }, []);
  useEffect(() => { void load(); }, [load, revision]);
  useEffect(() => { if (open) void load(); }, [open, load]);
  const close = () => { setOpen(false); trigger.current?.focus(); };
  return <div className="notifications"><button ref={trigger} className="secondary notification-trigger" aria-expanded={open} aria-controls="notification-panel" onClick={() => setOpen(value => !value)}>Notifications{items ? <span className="unread-count">{items.filter(item => !item.readAt).length}</span> : <span aria-label="Count unavailable">—</span>}</button>{open && <section id="notification-panel" className="notification-panel" aria-label="Private in-app notifications" onKeyDown={event => { if (event.key === 'Escape') close(); }}><div className="panel-title"><h2>Notifications</h2><button className="text-button" onClick={close} aria-label="Close notifications">×</button></div><p className="hint">Private updates for your account.</p>{error && <p className="error" role="alert">{error}<button className="text-button" onClick={() => void load()}>Retry</button></p>}{items === null && !error && <p role="status">Loading notifications…</p>}{items?.length === 0 && <p className="hint">No notifications have been recorded.</p>}<ul>{items?.map(item => <li key={text(item.id)} className={!item.readAt ? 'unread' : ''}><p>{text(item.message)}</p><time>{new Date(String(item.createdAt)).toLocaleString()}</time>{!item.readAt ? <button className="text-button" disabled={!!pending} onClick={() => { void (async () => { setPending(text(item.id)); setError(''); try { const id = text(item.id); let key = keys.current.get(id); if (!key) { key = crypto.randomUUID(); keys.current.set(id, key); } await request('/notifications/' + encodeURIComponent(id) + '/read', { method: 'POST', body: '{}', headers: { 'Idempotency-Key': key } }); keys.current.delete(id); await load(); } catch (error) { setError(error instanceof Error ? error.message : 'Unable to mark notification read.'); } finally { setPending(''); } })(); }}>{pending === item.id ? 'Saving…' : 'Mark as read'}</button> : <span className="hint">Read</span>}</li>)}</ul></section>}</div>;
}

function Complaints({ mode, rows, policies, revision, mutate }: { mode: 'customer' | 'admin'; rows: Item[]; policies: Item[]; revision: number; mutate: (url: string, body?: unknown, version?: unknown) => Promise<Item> }) {
  const [detail, setDetail] = useState<Item | null>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [report, setReport] = useState<Item | null>(null);
  const [reportError, setReportError] = useState('');
  const [reportLoading, setReportLoading] = useState(mode === 'admin');
  useEffect(() => { if (mode !== 'admin') return; let active = true; setReportLoading(true); setReportError(''); request('/complaints/report').then(result => { if (active) { setReport(result); setReportError(''); } }).catch(error => { if (active) { setReport(null); setReportError(error instanceof Error ? error.message : 'Report unavailable.'); } }).finally(() => { if (active) setReportLoading(false); }); return () => { active = false; }; }, [mode, revision]);
  async function open(id: unknown) { setError(''); setBusy(true); setDetail(null); try { setDetail(await request('/complaints/' + encodeURIComponent(text(id)))); } catch (error) { setError(error instanceof Error ? error.message : 'Complaint unavailable.'); } finally { setBusy(false); } }
  const status = text(detail?.status);
  const next = mode === 'customer' ? status === 'RESOLVED' ? [{ value: 'ESCALATED', label: 'Appeal the resolution' }, { value: 'CLOSED', label: 'Accept the resolution and close' }] : [] : ({ OPEN: [{ value: 'ACKNOWLEDGED', label: 'Acknowledge receipt' }], ACKNOWLEDGED: [{ value: 'INVESTIGATING', label: 'Begin investigation' }], INVESTIGATING: [{ value: 'RESOLVED', label: 'Record resolution' }], ESCALATED: [{ value: 'INVESTIGATING', label: 'Investigate the appeal' }] } as Record<string, { value: string; label: string }[]>)[status] || [];
  return <>{mode === 'admin' && <section className="complaint-report"><p className="eyebrow">Operational service targets</p>{reportLoading && <p className="hint" role="status">Loading the current service report…</p>}{reportError && <p className="error" role="alert">{reportError}</p>}{report && <><div className="complaint-metrics"><div><strong>{text(report.overdueCount)}</strong><span>Beyond service target</span></div><div><strong>{report.averageResolutionHours === null ? '—' : text(report.averageResolutionHours)}</strong><span>Average resolution hours</span></div><div><strong>{text(report.serviceTargetHours)}</strong><span>Service target hours</span></div></div><p className="hint">These are operational service targets. They do not represent statutory deadlines.</p><div className="complaint-counts">{(Array.isArray(report.counts) ? report.counts as Item[] : []).map(item => <span key={text(item.status)}><Status value={item.status} /> {text(item.count)}</span>)}</div></>}</section>}{mode === 'customer' && <Form title="Raise a complaint" submit="Submit complaint" fields={[{ name: 'policyId', label: 'Policy', options: policies.map(policy => ({ value: text(policy.id), label: text(policy.number) + ' · ' + text(policy.productName) })) }, { name: 'subject', label: 'Subject' }, { name: 'description', label: 'Describe your concern', type: 'textarea' }]} onSubmit={async (body, form) => { const result = await mutate('/complaints', body); form.reset(); await open(result.id); }}><p className="hint">The response and every status change will remain in your complaint history.</p></Form>}{!!rows.length && <Table rows={rows} columns={[{ label: 'Subject', key: 'subject' }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }, { label: 'Service target', key: 'dueAt', render: item => <>{date(item.dueAt)}{item.overdue === true && <span className="overdue-label">Beyond target</span>}</> }, { label: 'Created', key: 'createdAt', render: item => date(item.createdAt) }]} actions={item => <button className="secondary compact" onClick={() => void open(item.id)}>Open complaint</button>} />}{busy && <p role="status">Loading complaint history…</p>}{error && <p className="error" role="alert">{error}</p>}{detail && <section className="detail-panel complaint-detail" aria-label="Complaint details"><div className="panel-title"><h2>{text(detail.subject)}</h2><button className="text-button" onClick={() => setDetail(null)}>Close ×</button></div><Status value={detail.status} /><p className="contract-terms">{text(detail.description)}</p><dl className="certification-facts"><div><dt>Policy reference</dt><dd>{text(detail.policyId)}</dd></div><div><dt>Operational service target</dt><dd>{new Date(String(detail.dueAt)).toLocaleString()}{detail.overdue === true && <span className="overdue-label">Beyond target</span>}</dd></div></dl>{!!detail.resolution && <section className="complaint-resolution"><h3>Resolution</h3><p className="contract-terms">{text(detail.resolution)}</p></section>}<h3>Recorded history</h3><ol className="complaint-timeline">{(Array.isArray(detail.timeline) ? detail.timeline as Item[] : []).map((item, index) => <li key={text(item.id ?? index)}><Status value={item.status} /><time>{new Date(String(item.createdAt)).toLocaleString()}</time><p>{text(item.reason)}</p>{!!item.resolution && <p className="timeline-resolution"><strong>Recorded resolution: </strong>{text(item.resolution)}</p>}</li>)}</ol>{!!next.length && <Form key={text(detail.id) + ':' + text(detail.version)} title={mode === 'customer' ? 'Respond to this resolution' : 'Record the next step'} submit="Save complaint response" fields={[{ name: 'status', label: 'Next step', options: next, defaultValue: next.length === 1 ? next[0].value : undefined }, { name: 'reason', label: mode === 'customer' ? 'Reason for your response' : 'Reason for this step', type: 'textarea' }, ...(mode === 'admin' && status === 'INVESTIGATING' ? [{ name: 'resolution', label: 'Resolution provided to the customer', type: 'textarea' }] : [])]} onSubmit={async body => { await mutate('/complaints/' + detail.id + '/transitions', body, detail.version); await open(detail.id); }} />}</section>}</>;
}

export function Portal({ mode, section: requestedSection }: { mode: Mode; section?: string }) {
  const [user, setUser] = useState<User | null>(null);
  const partnerSections: Record<string, string[]> = { UNDERWRITER: ['underwriting'], ADJUSTER: ['claims'], FINANCE: ['claims', 'ledger', 'settlements'], FINANCE_APPROVER: ['claims', 'ledger', 'settlements', 'products', 'adapters'] };
  const navigation = mode === 'partner' && user ? menus[mode].filter(([key]) => (partnerSections[user.role] || []).includes(key)) : menus[mode];
  const section = requestedSection || navigation[0]?.[0] || menus[mode][0][0];
  const [authLoading, setAuthLoading] = useState(true);
  const [authError, setAuthError] = useState('');
  const [data, setData] = useState<unknown>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [notificationRevision, setNotificationRevision] = useState(0);
  const [workspaceRevision, setWorkspaceRevision] = useState(0);
  const [selected, setSelected] = useState<Item | null>(null);
  const [detail, setDetail] = useState<Item | null>(null);
  const [operation, setOperation] = useState<Item | null>(null);
  const [secret, setSecret] = useState('');
  const [products, setProducts] = useState<Item[]>([]);
  const [quoteProductId, setQuoteProductId] = useState('');
  const [claimPolicyId, setClaimPolicyId] = useState('');
  const [productCurrency, setProductCurrency] = useState('');
  const [reviewed, setReviewed] = useState(false);
  const [adapters, setAdapters] = useState<Item[]>([]);
  const [policies, setPolicies] = useState<Item[]>([]);
  const [draft, setDraft] = useState('');
  const mutationKeys = useRef(new Map<string, string>());
  const loadSequence = useRef(0);
  const allowedRoles: Record<Mode, string[]> = { customer: ['CUSTOMER'], partner: ['UNDERWRITER', 'ADJUSTER', 'FINANCE', 'FINANCE_APPROVER'], admin: ['ADMIN'], developer: ['DEVELOPER'] };
  useEffect(() => { setReviewed(false); }, [selected?.id, selected?.purchasing]);
  const verifyAuth = useCallback(async () => {
    setAuthLoading(true); setAuthError('');
    try { const result = await request('/auth/me'); setUser(result.user); }
    catch (error) { setUser(null); if (!(error instanceof ApiError && error.status === 401)) setAuthError(error instanceof Error ? error.message : 'Unable to check your session.'); }
    finally { setAuthLoading(false); }
  }, []);
  useEffect(() => { void verifyAuth(); }, [verifyAuth]);
  useEffect(() => { if (mode === 'customer' && 'serviceWorker' in navigator) void navigator.serviceWorker.register('/sw.js').catch(() => {}); }, [mode]);
  const path = section === 'complaints' && ['customer', 'admin'].includes(mode) ? '/complaints' : mode === 'partner' && ['products', 'adapters'].includes(section) ? '/admin/' + section : mode === 'admin' ? '/admin/' + section : mode === 'developer' ? section === 'docs' ? '/docs-json' : '/developer/' + section : section === 'marketplace' ? '/products' : '/' + section;
  const reload = useCallback(async () => {
    if (!user) return;
    const sequence = ++loadSequence.current;
    setLoading(true); setError('');
    try { const result = await request(path); if (sequence === loadSequence.current) { setData(result); setWorkspaceRevision(value => value + 1); } }
    catch (error) { if (sequence !== loadSequence.current) return; if (error instanceof ApiError && error.status === 401) setUser(null); setError(error instanceof Error ? error.message : 'Unable to load this workspace.'); }
    finally { if (sequence === loadSequence.current) setLoading(false); }
  }, [user, path]);
  useEffect(() => { setSelected(null); setDetail(null); setNotice(''); setSecret(''); setData(null); if (menus[mode].some(([key]) => key === section)) void reload(); return () => { loadSequence.current++; }; }, [reload, section, mode]);
  useEffect(() => {
    if (!user || mode !== 'customer') return;
    if (section === 'quotes') request('/products').then(setProducts).catch(error => setError(error instanceof Error ? error.message : 'Unable to load products.'));
    if (['claims', 'complaints'].includes(section)) request('/policies').then(setPolicies).catch(error => setError(error instanceof Error ? error.message : 'Unable to load policies.'));
  }, [user, mode, section]);
  useEffect(() => {
    if (!user || !['admin', 'partner'].includes(mode) || section !== 'products') return;
    request('/admin/adapters').then(setAdapters).catch(error => setError(error instanceof Error ? error.message : 'Unable to load the provider registry.'));
  }, [user, mode, section]);
  useEffect(() => {
    if (!operation || !operation.operationId || ['COMPLETED', 'FAILED', 'SUCCEEDED', 'ISSUED'].includes(text(operation.status))) return;
    const interval = setInterval(() => { request('/operations/' + encodeURIComponent(text(operation.operationId))).then(result => { setOperation(result); if (['COMPLETED', 'SUCCEEDED', 'ISSUED'].includes(result.status)) void reload(); }).catch(error => setError(error instanceof Error ? error.message : 'Unable to check purchase status.')); }, 3000);
    return () => clearInterval(interval);
  }, [operation, reload]);
  async function mutate(url: string, body: unknown = {}, version?: unknown, method = 'POST') {
    const fingerprint = method + url + JSON.stringify(body);
    let key = mutationKeys.current.get(fingerprint);
    if (!key) { key = crypto.randomUUID(); mutationKeys.current.set(fingerprint, key); }
    const headers: Record<string, string> = { 'Idempotency-Key': key };
    if (version !== undefined) headers['If-Match'] = String(version);
    const result = await request(url, { method, headers, body: method === 'DELETE' ? undefined : JSON.stringify(body) });
    mutationKeys.current.delete(fingerprint);
    setNotice('Your request was saved.'); setNotificationRevision(value => value + 1); await reload(); return result;
  }
  async function action(run: () => Promise<unknown>) { setError(''); try { await run(); } catch (error) { setError(error instanceof Error ? error.message : 'The request failed.'); } }
  async function logout() { await action(async () => { await mutate('/auth/logout'); setUser(null); setData(null); setSecret(''); localStorage.removeItem('coverline-fnol-policy'); }); }
  if (authLoading) return <main className="standalone" aria-busy="true"><div className="brand">C<span>Coverline</span></div><p>Opening your secure workspace…</p></main>;
  if (!user) return <main className="login"><section className="login-story"><div className="brand">C<span>Coverline</span></div><div><p className="eyebrow">{mode} portal</p><h1>Confidence, <br />in every <br /><em>next step.</em></h1><p>One secure workspace for your insurance journey.</p></div><p className="login-caption">Clear cover. Considered decisions.</p></section><section className="login-form"><p className="eyebrow">Welcome back</p><Form title="Sign in to your workspace" submit="Sign in" fields={[{ name: 'email', label: 'Email address', type: 'email' }, { name: 'password', label: 'Password', type: 'password' }, { name: 'totp', label: 'Authenticator code', required: false, placeholder: 'Required for staff with MFA' }]} onSubmit={async body => { const result = await request('/auth/login', { method: 'POST', body: JSON.stringify({ email: body.email, password: body.password, ...(body.totp ? { totp: body.totp } : {}) }) }); setUser(result.user); }} /><p className="hint">Use an account provided by your organization. Staff accounts may require an authenticator code.</p>{process.env.NODE_ENV !== 'production' && <details><summary>Local development accounts</summary><p className="hint">{mode === 'partner' ? 'underwriter@example.test · adjuster@example.test · finance@example.test · approver@example.test' : mode + '@example.test'}<br />Read the generated password from <code>.local/demo-password</code>.</p></details>}{authError && <div className="error" role="alert">{authError}<button className="text-button" onClick={() => void verifyAuth()}>Retry connection</button></div>}</section></main>;
  const title = menus[mode].find(([key]) => key === section)?.[1];
  const rows = Array.isArray(data) ? data as Item[] : [];
  const policyOptions = policies.map(policy => ({ value: text(policy.id), label: text(policy.number) + ' · ' + text(policy.productName) }));
  const productOptions = products.map(product => ({ value: text(product.id), label: text(product.name) }));
  const claimColumns = [{ label: 'Claim', key: 'id' }, { label: 'Incident', key: 'description' }, { label: 'Requested', key: 'requestedMinor', render: (item: Item) => money(item.requestedMinor, item.currency) }, { label: 'Approved', key: 'approvedMinor', render: (item: Item) => money(item.approvedMinor, item.currency) }, { label: 'Status', key: 'status', render: (item: Item) => <Status value={item.status} /> }];
  return <div className="app-shell"><aside className="sidebar"><Link href="/" className="brand">C<span>Coverline</span></Link><p className="workspace-label">{mode} workspace</p><nav aria-label="Workspace">{navigation.map(([key, label], index) => <Link aria-current={section === key ? 'page' : undefined} key={key} href={'/' + key}><span className="nav-number">0{index + 1}</span>{label}<span className="nav-arrow" aria-hidden="true">↗</span></Link>)}</nav><div className="sidebar-bottom"><span className="connection-dot" />Secure session<p>{user.name || user.email}</p><small>{user.role.replaceAll('_', ' ')}</small><button className="text-button" onClick={() => void logout()}>Sign out →</button></div></aside><div className="main-shell"><header className="topbar"><span className="topbar-tagline">Insurance, with clarity.</span><span className="tenant-label">Organization <code>{user.tenantId.slice(0, 8)}</code></span><Notifications key={user.id} revision={notificationRevision} /><button className="text-button mobile-signout" onClick={() => void logout()}>Sign out</button></header><main><header className="page-header"><div><p className="eyebrow">Coverline / {mode}</p><h1>{title || 'Page not found'}</h1><p>{mode === 'partner' && section === 'claims' ? 'Review losses and record assessments, independent approvals and approved payouts.' : descriptions[section]}</p></div><button className="secondary" onClick={() => void reload()} disabled={loading}>{loading ? 'Refreshing…' : 'Refresh ↻'}</button></header>{!allowedRoles[mode].includes(user.role) ? <div className="error" role="alert">This account does not have access to the {mode} workspace. Sign in using the appropriate organization account.</div> : !title ? <Empty>Choose a workspace from the navigation.</Empty> : <>{notice && <div className="notice" role="status">{notice}<button aria-label="Dismiss notification" className="text-button" onClick={() => setNotice('')}>×</button></div>}{error && <div className="error" role="alert">{error}<button className="text-button" onClick={() => void reload()}>Try again</button></div>}{loading && <div className="loading-bar" role="status">Loading current records…</div>}
  {mode === 'customer' && section === 'marketplace' && <><div className="editorial-note"><span className="note-index">01 / COVER FOR WHAT MATTERS</span><h2>A little preparation.<br /><em>A lot of peace of mind.</em></h2><p>Published coverage, transparent terms and prices calculated by your insurer.</p></div><div className="product-list">{rows.map(product => <article className="product" key={text(product.id)}><div><p className="eyebrow">{text(product.insurerName)} / {text(product.category)}</p><h2>{text(product.name)}</h2>{product.sandbox === true && <p className="sandbox-label">Local sandbox · demonstration coverage</p>}<p>{text(product.description)}</p><div className="coverage-list">{(Array.isArray(product.coverages) ? product.coverages as Item[] : []).map(coverage => <span key={text(coverage.code)}>{text(coverage.name)}<b>{money(coverage.limitMinor, product.currency)}</b></span>)}</div></div><div className="product-price"><small>Base premium</small><strong>{money(product.basePremiumMinor, product.currency)}</strong><small>Final price depends on your application.</small><button onClick={() => setSelected(product)}>Get a quote →</button></div></article>)}</div>{selected && <Form title={'Quote for ' + text(selected.name)} submit="Calculate my quote" fields={[{ name: 'age', label: 'Applicant age', type: 'number', min: '18', max: '100' }, { name: 'assetValue', label: 'Asset value', type: 'money', currency: selected.currency }]} onSubmit={async (body, form) => { await mutate('/quotes', { productId: selected.id, age: Number(body.age), assetValueMinor: parseMoney(body.assetValue, selected.currency), coverageCodes: new FormData(form).getAll('coverageCodes') }); setSelected(null); setNotice('Your quote was created. Open Your quotes to review its status and price.'); }}><CoverageChoices product={selected} /><p className="hint">Applicants over 70 are referred for underwriting. Enter the asset value in the displayed currency using a decimal point.</p></Form>}</>}
  {mode === 'customer' && section === 'quotes' && <><Form title="Start a new quote" submit="Calculate quote" fields={[{ name: 'productId', label: 'Product', options: productOptions }, { name: 'age', label: 'Applicant age', type: 'number', min: '18', max: '100' }, { name: 'assetValue', label: 'Asset value', type: 'money', currency: products.find(item => item.id === quoteProductId)?.currency }]} onChange={form => setQuoteProductId(String(new FormData(form).get('productId') || ''))} onSubmit={async (body, form) => { await mutate('/quotes', { productId: body.productId, assetValueMinor: parseMoney(body.assetValue, products.find(item => item.id === body.productId)?.currency), age: Number(body.age), coverageCodes: new FormData(form).getAll('coverageCodes') }); }}>{products.find(item => item.id === quoteProductId) && <CoverageChoices key={quoteProductId} product={products.find(item => item.id === quoteProductId)!} />}</Form>{!!rows.length && <Table rows={rows} columns={[{ label: 'Product', key: 'productName' }, { label: 'Insurer', key: 'insurerName' }, { label: 'Premium', key: 'totalMinor', render: item => money(item.totalMinor, item.currency) }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }, { label: 'Expires', key: 'expiresAt', render: item => date(item.expiresAt) }]} actions={item => <><button className="secondary compact" onClick={() => setSelected(item)}>Details</button>{text(item.status) === 'READY' && <button className="compact" onClick={() => setSelected({ ...item, purchasing: true })}>Review purchase</button>}</>} />}{selected && <section className="detail-panel"><h2>{selected.purchasing ? 'Confirm your coverage' : 'Quote details'}</h2><p>{text(selected.productName)} · {money(selected.totalMinor, selected.currency)}</p><QuoteReview quote={selected} /><Table rows={Array.isArray(selected.breakdown) ? selected.breakdown as Item[] : []} columns={[{ label: "Price component", key: "name" }, { label: "Amount", key: "amountMinor", render: item => money(item.amountMinor, selected.currency) }]} />{!!selected.purchasing && <><p>{selected.sandbox === true && <strong>Local sandbox payment and insurer adapter. This purchase creates demonstration coverage. </strong>}Confirm you have reviewed the product coverage and premium. Your policy will be issued when payment and insurer confirmation complete.</p><label className="check-field purchase-ack"><input type="checkbox" checked={reviewed} onChange={event => setReviewed(event.target.checked)} />I have reviewed the coverage, deductibles and contract terms.</label><button disabled={!reviewed || !Array.isArray(selected.coverages) || selected.coverages.length === 0 || typeof selected.terms !== 'string' || !selected.terms.trim()} onClick={() => void action(async () => { setOperation(await mutate('/quotes/' + selected.id + '/purchase', {}, selected.version)); setSelected(null); })}>Confirm purchase →</button></>}<button className="text-button" onClick={() => setSelected(null)}>Close</button></section>}{operation && <div className={operation.status === 'FAILED' ? 'error' : 'notice'} role={operation.status === 'FAILED' ? 'alert' : 'status'}><div><p>Purchase {text(operation.operationId)}: <Status value={operation.status} /></p><p>Stage: {text(operation.stage)}{operation.errorCode ? <> · Error code: <code>{text(operation.errorCode)}</code></> : null}</p>{operation.stage === 'REFUNDED' && <p>Payment was refunded after the insurer declined the purchase. No policy was issued.</p>}{operation.stage === 'PAYMENT_DECLINED' && <p>Payment was declined. No policy was issued.</p>}{operation.policyId ? <Link href="/policies"> View policy →</Link> : null}</div><button className="text-button" onClick={() => void action(async () => setOperation(await request('/operations/' + operation.operationId)))}>Check status</button></div>}</>}
  {mode === 'customer' && section === 'policies' && <>{!!rows.length && <Table rows={rows} columns={[{ label: 'Policy', key: 'number' }, { label: 'Coverage', key: 'productName' }, { label: 'Premium', key: 'premiumMinor', render: item => money(item.premiumMinor, item.currency) }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }, { label: 'Expires', key: 'expiresAt', render: item => date(item.expiresAt) }]} actions={item => <><a className="button secondary compact" href={'/api/policies/' + encodeURIComponent(text(item.id)) + '/document'}>Document ↗</a><button className="secondary compact" onClick={() => setSelected(item)}>Manage</button></>} />}{selected && <div className="workbench"><Form title={'Update ' + text(selected.number)} fields={[{ name: 'address', label: 'New address' }, { name: 'reason', label: 'Reason', type: 'textarea' }]} submit="Request endorsement" onSubmit={async body => { await mutate('/policies/' + selected.id + '/endorsements', body, selected.version); setSelected(null); }} /><section className="form-panel"><h2>Renew your cover</h2><p>Submit a renewal request for this policy. Pricing and eligibility are reviewed by the insurer.</p><button onClick={() => void action(async () => { await mutate('/policies/' + selected.id + '/renewals', {}, selected.version); setSelected(null); setNotice('Renewal quote created. Open Your quotes to review and purchase it.'); })}>Request renewal →</button></section><Form title="Cancel this policy" submit="Request cancellation" fields={[{ name: 'reason', label: 'Cancellation reason', type: 'textarea' }]} onSubmit={async body => { await mutate('/policies/' + selected.id + '/cancellations', body, selected.version); setSelected(null); }} /></div>}</>}
  {section === 'claims' && <>{mode === 'customer' && <Form title="Tell us what happened" submit="Report incident" fields={[{ name: 'policyId', label: 'Policy', options: policyOptions }, { name: 'incidentAt', label: 'Incident date and time', type: 'datetime-local' }, { name: 'description', label: 'What happened?', type: 'textarea', placeholder: 'A brief description is enough to start.' }, { name: 'amount', label: 'Requested amount', type: 'money', currency: policies.find(item => item.id === claimPolicyId)?.currency }]} onChange={form => setClaimPolicyId(String(new FormData(form).get('policyId') || ''))} onSubmit={async (body, form) => { const result = await mutate('/claims', { policyId: body.policyId, incidentAt: new Date(body.incidentAt).toISOString(), description: body.description, amountMinor: parseMoney(body.amount, policies.find(item => item.id === body.policyId)?.currency) }); setDetail(await request('/claims/' + result.id)); form.reset(); }}><div className="draft-tools"><label className="check-field"><input type="checkbox" name="saveDraft" onChange={event => { if (!event.target.checked) localStorage.removeItem('coverline-fnol-policy'); }} />Allow a minimal offline draft of the policy reference only</label><button type="button" className="text-button" onClick={event => { const form = event.currentTarget.form; if (form && new FormData(form).get('saveDraft')) { localStorage.setItem('coverline-fnol-policy', String(new FormData(form).get('policyId') || '')); setDraft('Policy reference saved on this device. Incident details and documents are never stored.'); } }}>Save policy reference</button><button type="button" className="text-button" onClick={event => { const value = localStorage.getItem('coverline-fnol-policy'); const select = event.currentTarget.form?.elements.namedItem('policyId'); if (value && select instanceof HTMLSelectElement) { select.value = value; setClaimPolicyId(select.value); } setDraft(value ? 'Saved policy reference restored.' : 'No offline draft is saved.'); }}>Restore reference</button>{draft && <p role="status" className="hint">{draft}</p>}</div></Form>}{!!rows.length && <Table rows={rows} columns={claimColumns} actions={item => <button className="secondary compact" onClick={() => void action(async () => setDetail(await request('/claims/' + item.id)))}>Open claim →</button>} />}{detail && <section className="detail-panel"><div className="panel-title"><h2>Claim {text(detail.id).slice(0, 8)}</h2><button className="text-button" onClick={() => setDetail(null)}>Close ×</button></div><p>{text(detail.description)}</p><Status value={detail.status} /><dl className="fact-list"><div><dt>Requested</dt><dd>{money(detail.requestedMinor, detail.currency)}</dd></div><div><dt>Approved</dt><dd>{money(detail.approvedMinor, detail.currency)}</dd></div><div><dt>Paid</dt><dd>{money(detail.paidMinor, detail.currency)}</dd></div></dl>{mode === 'customer' && <Form title="Add supporting evidence" submit="Upload document" fields={[{ name: 'file', label: 'Document (up to 10 MB)', type: 'file' }]} onSubmit={async (_, form) => { const body = new FormData(form); const file = body.get('file'); if (!(file instanceof File) || !file.size || file.size > 10 * 1024 * 1024) throw new Error('Choose a document smaller than 10 MB.'); const fingerprint = 'upload:' + detail.id + ':' + file.name + ':' + file.size + ':' + file.lastModified; let key = mutationKeys.current.get(fingerprint); if (!key) { key = crypto.randomUUID(); mutationKeys.current.set(fingerprint, key); } await request('/claims/' + detail.id + '/documents', { method: 'POST', body, headers: { 'Idempotency-Key': key, 'If-Match': String(detail.version) } }); mutationKeys.current.delete(fingerprint); setDetail(await request('/claims/' + detail.id)); setNotice('Document uploaded.'); }} />}{Array.isArray(detail.documents) && <ul className="document-list">{(detail.documents as Item[]).map(document => <li key={text(document.id)}>{text(document.filename ?? document.name)}<div className="row-actions"><Status value={document.status ?? 'RECEIVED'} />{text(document.status) === 'CLEAN' && <a className="button secondary compact" href={'/api/documents/' + encodeURIComponent(text(document.id))}>Download ↗</a>}</div></li>)}</ul>}{mode === 'partner' && user.role === 'ADJUSTER' && detail.status === 'OPEN' && <Form title="Record assessment" submit="Record decision" fields={[{ name: 'amount', label: 'Approved amount', type: 'money', currency: detail.currency }, { name: 'reason', label: 'Assessment reason', type: 'textarea' }]} onSubmit={async body => { await mutate('/claims/' + detail.id + '/decisions', { amountMinor: parseMoney(body.amount, detail.currency), reason: body.reason }, detail.version); setDetail(await request('/claims/' + detail.id)); }} />}{mode === 'partner' && user.role === 'ADJUSTER' && detail.status === 'OPEN' && <Form title="Propose a claim decline" submit="Submit for independent review" fields={[{ name: 'reason', label: 'Decline proposal rationale', type: 'textarea' }]} onSubmit={async body => { await mutate('/claims/' + detail.id + '/decline-proposals', body, detail.version); setDetail(await request('/claims/' + detail.id)); }}><p className="hint">An independent approver must review this proposal before the claim can be declined.</p></Form>}{mode === 'partner' && user.role === 'FINANCE_APPROVER' && ['PENDING_APPROVAL', 'PENDING_DECLINE'].includes(text(detail.status)) && <Form title={detail.status === 'PENDING_DECLINE' ? 'Independent decline review' : 'Independent approval'} submit={detail.status === 'PENDING_DECLINE' ? 'Approve proposed decline' : 'Approve claim'} fields={[{ name: 'reason', label: 'Approval rationale', type: 'textarea' }]} onSubmit={async body => { await mutate('/claims/' + detail.id + '/approvals', body, detail.version); setDetail(await request('/claims/' + detail.id)); }} />}{mode === 'partner' && user.role === 'FINANCE' && <button onClick={() => void action(async () => { await mutate('/claims/' + detail.id + '/payouts', {}, detail.version); setDetail(await request('/claims/' + detail.id)); })}>Request approved payout →</button>}</section>}</>}
  {section === 'complaints' && (mode === 'customer' || mode === 'admin') && <Complaints mode={mode} rows={rows} policies={policies} revision={workspaceRevision} mutate={mutate} />}
  {mode === 'partner' && section === 'underwriting' && <>{!!rows.length && <Table rows={rows} columns={[{ label: 'Quote', key: 'id' }, { label: 'Product', key: 'productName' }, { label: 'Premium', key: 'totalMinor', render: item => money(item.totalMinor, item.currency) }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }]} actions={item => user.role === 'UNDERWRITER' ? <button className="secondary compact" onClick={() => setSelected(item)}>Review</button> : <span className="hint">Underwriter required</span>} />}{selected && <Form title={'Decision for quote ' + text(selected.id)} submit="Record underwriting decision" fields={[{ name: 'decision', label: 'Decision', options: [{ value: 'ACCEPT', label: 'Accept' }, { value: 'DECLINE', label: 'Decline' }] }, { name: 'reason', label: 'Decision reason', type: 'textarea' }]} onSubmit={async body => { await mutate('/quotes/' + selected.id + '/underwriting', body, selected.version); setSelected(null); }} />}</>}
  {mode === 'partner' && section === 'ledger' && !!data && !Array.isArray(data) && <><h2 className="section-title">Account balances</h2><Table rows={(data as { balances: Item[] }).balances || []} columns={[{ label: 'Account', key: 'account' }, { label: 'Balance', key: 'balanceMinor', render: item => money(item.balanceMinor, item.currency) }]} /><h2 className="section-title">Journal entries</h2>{((data as { entries: Item[] }).entries || []).map(entry => <article className="ledger-entry" key={text(entry.id)}><div className="panel-title"><h3>{text(entry.reference)}</h3><time>{date(entry.createdAt)}</time></div><Table rows={entry.postings as Item[] || []} columns={[{ label: 'Account', key: 'account' }, { label: 'Side', key: 'side' }, { label: 'Amount', key: 'amountMinor', render: item => money(item.amountMinor, entry.currency) }]} /></article>)}</>}
  {mode === 'partner' && section === 'settlements' && <>{user.role === 'FINANCE' && <Form title="Create a settlement batch" fields={[{ name: 'reason', label: 'Batch reason', type: 'textarea' }]} submit="Create settlement" onSubmit={async body => { await mutate('/settlements', body); }} />}{!!rows.length && <Table rows={rows} columns={[{ label: 'Batch', key: 'id' }, { label: 'Amount', key: 'amountMinor', render: item => money(item.amountMinor, item.currency) }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }, { label: 'Created', key: 'createdAt', render: item => date(item.createdAt) }]} actions={item => <>{user.role === 'FINANCE_APPROVER' && <button className="secondary compact" onClick={() => setSelected({ ...item, settlementAction: 'approvals' })}>Review approval</button>}{user.role === 'FINANCE' && <button className="secondary compact" onClick={() => setSelected({ ...item, settlementAction: 'payouts' })}>Review payout</button>}</>} />}{selected && <section className="form-panel"><h2>Confirm settlement {text(selected.settlementAction)}</h2><p>Batch {text(selected.id)}. The service validates approval separation and batch eligibility before processing.</p><button onClick={() => void action(async () => { await mutate('/settlements/' + selected.id + '/' + selected.settlementAction, {}, selected.version); setSelected(null); })}>Confirm →</button><button className="text-button" onClick={() => setSelected(null)}>Cancel</button></section>}</>}
  {mode === 'admin' && section === 'overview' && !!data && <><div className="notice">Deployment mode: {text((data as Item).deploymentMode)}</div><div className="overview-stats">{Object.entries(data as Item).filter(([, value]) => typeof value === 'number').map(([key, value], index) => <article key={key}><span className="note-index">0{index + 1}</span><h2>{text(value)}</h2><p>{key.replace(/([A-Z])/g, ' $1')}</p></article>)}</div></>}
  {mode === 'admin' && section === 'tenants' && !!rows.length && <Table rows={rows} columns={[{ label: 'Organization', key: 'name' }, { label: 'Identifier', key: 'id' }, { label: 'Type', key: 'kind' }]} />}
  {mode === 'admin' && section === 'products' && <Form title="Create a product draft" submit="Create immutable draft" fields={[{ name: 'name', label: 'Product name' }, { name: 'category', label: 'Category' }, { name: 'description', label: 'Description', type: 'textarea' }, { name: 'currency', label: 'ISO currency code', placeholder: 'USD' }, { name: 'basePremium', label: 'Base premium', type: 'money', currency: productCurrency }, { name: 'coverageCode', label: 'Coverage code' }, { name: 'coverageName', label: 'Coverage name' }, { name: 'limit', label: 'Coverage limit', type: 'money', currency: productCurrency }, { name: 'deductible', label: 'Deductible', type: 'money', currency: productCurrency }]} onChange={form => setProductCurrency(String(new FormData(form).get('currency') || '').trim().toUpperCase())} onSubmit={async (body, form) => { let definition: unknown; if (body.ratingRules?.trim()) { try { definition = JSON.parse(body.ratingRules); } catch { throw new Error('Rating definition must be valid JSON.'); } } const advanced: Record<string, unknown> = {}; for (const name of ['jurisdiction', 'terms', 'certificationReference', 'carrierAdapterId', 'paymentAdapterId']) if (body[name]?.trim()) advanced[name] = body[name].trim(); if (definition !== undefined) advanced.ratingRules = definition; await mutate('/admin/products', { ...advanced, name: body.name, category: body.category, description: body.description, currency: body.currency.trim().toUpperCase(), basePremiumMinor: parseMoney(body.basePremium, body.currency.trim().toUpperCase()), coverages: [{ code: body.coverageCode, name: body.coverageName, limitMinor: parseMoney(body.limit, body.currency.trim().toUpperCase()), deductibleMinor: parseMoney(body.deductible, body.currency.trim().toUpperCase()) }] }); form.reset(); }}><AdvancedProductFields adapters={adapters} /><p className="hint">A new immutable draft requires an independent FINANCE_APPROVER to publish it. Customers see published versions only.</p></Form>}
  {section === 'products' && (mode === 'admin' || mode === 'partner') && !!rows.length && <Table rows={rows} columns={[{ label: 'Product', key: 'name' }, { label: 'Version', key: 'versionId' }, { label: 'Jurisdiction', key: 'jurisdiction' }, { label: 'Premium', key: 'basePremiumMinor', render: item => money(item.basePremiumMinor, item.currency) }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }]} actions={mode === 'partner' ? item => user.role === 'FINANCE_APPROVER' && text(item.status) === 'DRAFT' ? <button className="secondary compact" onClick={() => setSelected(item)}>Review publication</button> : <span className="hint">Independent approver required</span> : undefined} />}
  {mode === 'partner' && section === 'products' && selected && <section className="form-panel"><h2>Publish {text(selected.name)}?</h2><dl className="certification-facts"><div><dt>Jurisdiction</dt><dd>{text(selected.jurisdiction)}</dd></div><div><dt>Certification reference</dt><dd>{text(selected.certificationReference)}</dd></div><div><dt>Carrier binding</dt><dd>{text(adapters.find(adapter => adapter.id === selected.carrierAdapterId)?.name ?? selected.carrierAdapterId)}</dd></div><div><dt>Payment binding</dt><dd>{text(adapters.find(adapter => adapter.id === selected.paymentAdapterId)?.name ?? selected.paymentAdapterId)}</dd></div></dl>{!!selected.terms && <details><summary>Review contract terms</summary><p className="contract-terms">{text(selected.terms)}</p></details>}{!!selected.ratingRules && <details><summary>Review effective rating definition</summary><pre>{JSON.stringify(selected.ratingRules, null, 2)}</pre></details>}<p>This publishes immutable version {text(selected.versionId)} to the customer marketplace. The platform verifies that the approver is independent of its creator.</p><button onClick={() => void action(async () => { await mutate('/admin/products/' + selected.versionId + '/publications', {}, selected.version); setSelected(null); })}>Confirm publication →</button><button className="text-button" onClick={() => setSelected(null)}>Cancel</button></section>}
  {mode === 'admin' && section === 'adapters' && <Form title="Create a provider version draft" submit="Create provider draft" fields={[{ name: 'kind', label: 'Provider kind', options: [{ value: 'CARRIER', label: 'Carrier' }, { value: 'PAYMENT', label: 'Payment' }] }, { name: 'name', label: 'Provider name' }, { name: 'version', label: 'Certified provider version' }, { name: 'endpoint', label: 'Approved HTTPS endpoint', type: 'url', placeholder: 'https://approved-provider.example/api' }, { name: 'credential', label: 'Provider credential', type: 'password' }, { name: 'certificationReference', label: 'Certification reference', type: 'textarea' }]} onSubmit={async (body, form) => { await mutate('/admin/adapters', body); form.reset(); }}><p className="hint">The service accepts operator-approved HTTPS destinations only. Credentials are encrypted by the service and are not returned in the registry. An independent FINANCE_APPROVER must approve this version.</p></Form>}
  {['admin', 'partner'].includes(mode) && section === 'adapters' && !!rows.length && <Table rows={rows} columns={[{ label: 'Provider', key: 'name' }, { label: 'Kind', key: 'kind' }, { label: 'Version', key: 'version' }, { label: 'Endpoint', key: 'endpoint' }, { label: 'Certification', key: 'certificationReference' }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }]} actions={mode === 'partner' ? item => user.role === 'FINANCE_APPROVER' && item.status === 'DRAFT' ? <button className="secondary compact" onClick={() => setSelected(item)}>Review provider</button> : <span className="hint">{item.status === 'APPROVED' ? 'Approved immutable version' : 'Independent approver required'}</span> : undefined} />}
  {mode === 'partner' && section === 'adapters' && selected && <section className="detail-panel"><h2>Approve provider version?</h2><dl className="certification-facts"><div><dt>Provider</dt><dd>{text(selected.name)}</dd></div><div><dt>Kind / version</dt><dd>{text(selected.kind)} / {text(selected.version)}</dd></div><div><dt>HTTPS endpoint</dt><dd>{text(selected.endpoint)}</dd></div><div><dt>Certification reference</dt><dd>{text(selected.certificationReference)}</dd></div></dl><p>Review the provider endpoint, exact version and certification before approval. The platform verifies that you are independent of its creator. Approved versions can be bound to certified live products.</p><button onClick={() => void action(async () => { await mutate('/admin/adapters/' + selected.id + '/approvals'); setSelected(null); })}>Approve provider version →</button><button className="text-button" onClick={() => setSelected(null)}>Cancel</button></section>}
  {mode === 'admin' && section === 'audit' && !!rows.length && <Table rows={rows} columns={[{ label: 'Action', key: 'action' }, { label: 'Actor', key: 'actorId' }, { label: 'Resource', key: 'resourceId' }, { label: 'When', key: 'createdAt', render: item => date(item.createdAt) }]} />}
  {mode === 'developer' && section === 'keys' && <><Form title="Create an API credential" fields={[{ name: 'name', label: 'Credential name', placeholder: 'e.g. Policy integration' }]} submit="Create credential" onSubmit={async body => { const result = await mutate('/developer/keys', body); setSecret(result.secret || result.key || result.apiKey || ''); }} />{secret && <section className="secret-panel"><h2>Save your secret now</h2><p>This secret is displayed once. Store it securely in your application environment.</p><code>{secret}</code><button className="secondary" onClick={() => void action(async () => { await navigator.clipboard.writeText(secret); setNotice('Secret copied.'); })}>Copy secret</button><button className="text-button" onClick={() => setSecret('')}>Dismiss secret</button></section>}{!!rows.length && <Table rows={rows} columns={[{ label: 'Name', key: 'name' }, { label: 'Prefix', key: 'prefix' }, { label: 'Created', key: 'createdAt', render: item => date(item.createdAt) }, { label: 'Status', key: 'status', render: item => <Status value={item.status ?? (item.revokedAt ? 'REVOKED' : 'ACTIVE')} /> }]} actions={item => <button className="secondary compact" onClick={() => setSelected(item)}>Revoke</button>} />}{selected && <section className="form-panel"><h2>Revoke {text(selected.name)}?</h2><p>Applications using this credential will lose access immediately.</p><button onClick={() => void action(async () => { await mutate('/developer/keys/' + selected.id, undefined, undefined, 'DELETE'); setSelected(null); })}>Confirm revocation</button><button className="text-button" onClick={() => setSelected(null)}>Cancel</button></section>}</>}
  {mode === 'developer' && section === 'webhooks' && <><Form title="Register a webhook" fields={[{ name: 'url', label: 'HTTPS endpoint', type: 'url', placeholder: 'https://your-service.example/events' }]} submit="Register endpoint" onSubmit={async body => { const result = await mutate('/developer/webhooks', body); setSecret(result.signingSecret || ''); }}><p className="hint">Only approved HTTPS hostnames can receive events. Registration may be rejected if your hostname is not approved.</p></Form>{!!rows.length && <Table rows={rows} columns={[{ label: 'Endpoint', key: 'url' }, { label: 'Status', key: 'status', render: item => <Status value={item.status ?? (item.active === true ? 'ACTIVE' : 'PAUSED')} /> }, { label: 'Created', key: 'createdAt', render: item => date(item.createdAt) }]} />}</>}
  {mode === 'developer' && section === 'webhooks' && secret && <section className="secret-panel"><h2>Save your webhook signing secret</h2><p>This secret is displayed once. Use it to verify incoming webhook signatures and store it securely.</p><code>{secret}</code><button className="secondary" onClick={() => void action(async () => { await navigator.clipboard.writeText(secret); setNotice('Signing secret copied.'); })}>Copy signing secret</button><button className="text-button" onClick={() => setSecret('')}>Dismiss secret</button></section>}
  {mode === 'developer' && section === 'logs' && !!rows.length && <Table rows={rows} columns={[{ label: 'Delivery', key: 'id' }, { label: 'Event', key: 'eventId' }, { label: 'Status', key: 'status', render: item => <Status value={item.status} /> }, { label: 'Attempts', key: 'attempts' }, { label: 'HTTP result', key: 'httpStatus' }, { label: 'Next attempt', key: 'nextAttemptAt', render: item => item.nextAttemptAt ? new Date(String(item.nextAttemptAt)).toLocaleString() : '—' }]} />}
  {mode === 'developer' && section === 'docs' && !!data && <section className="api-reference"><div className="panel-title"><h2>Live API contract</h2><div className="row-actions"><button className="secondary" onClick={() => void action(async () => { const health = await request("/health/ready"); setNotice("Service readiness: " + text(health.status ?? health.ready ?? health)); })}>Check readiness</button><a href="/api/docs-json" className="button secondary" download="openapi.json">Download OpenAPI ↗</a></div></div><p>Use cookie authentication through your portal or a server-held API credential for integrations. Mutations require an Idempotency-Key. Pass If-Match for versioned updates.</p><pre>{'POST /api/quotes\nIdempotency-Key: <unique-request-id>\nContent-Type: application/json\n\n{ "productId": "…", "age": 35, "assetValueMinor": "250000", "coverageCodes": ["…"] }'}</pre>{Object.entries((data as { paths?: Record<string, Item> }).paths || {}).map(([path, methods]) => <details key={path}><summary><code>{path}</code><span>{Object.keys(methods).join(' / ').toUpperCase()}</span></summary><pre>{JSON.stringify(methods, null, 2)}</pre></details>)}</section>}
  {!loading && !error && Array.isArray(data) && !rows.length && <Empty>{section === 'marketplace' ? 'Your organization has no published products yet.' : 'New records will appear here as you complete the workflow above.'}</Empty>}
  </>}</main><footer><span>Coverline / {mode} workspace</span><span>Amounts shown in their recorded currency.</span></footer></div></div>;
}
